fn is_prime(n: i8) -> bool {
    // Any number less than 2 is not prime
    let n = n as i32;
    if n < 2 {
        return false;
    }

    // Try every divisor from 2 up to n - 1
    let mut divisor = 2;
    while divisor < n {
        if n % divisor == 0 {
            return false;
        }
        divisor += 1;
    }

    // No divisors found, it's prime
    true
}

